        $claim=$this->tx($issuer,$actor,function()use($issuer,$actor,$id,$through){$this->access($issuer,$actor);$r=$this->owned($issuer,$actor,$id,true);if((int)$r['actor_id']!==$actor)throw new DomainException('company_sales_denied');if(in_array($r['state'],['paused','completed'],true)||$r['next_date']>$through)return null;if(!in_array($r['state'],['active','processing'],true))throw new DomainException('company_sales_state_conflict');$payload=$this->decode($r['payload_json']);$key=hash('sha256','company-recurring-invoice:'.$issuer.':'.$id.':'.$r['next_date']);$this->assertOriginOrReceipt($issuer,$actor,$payload,$r['origin_hash'],$this->decode($r['context_json']),$key);$run=$this->rows('SELECT * FROM '.$this->prefix.'company_recurring_runs WHERE request_key=? FOR UPDATE',[$key])[0]??null;if(!$run){$this->insert('company_recurring_runs',['request_key'=>$key,'issuer_id'=>$issuer,'schedule_id'=>$id,'run_date'=>$r['next_date'],'invoice_id'=>0,'state'=>'processing','created_at'=>date('Y-m-d H:i:s')]);}$run=$this->rows('SELECT * FROM '.$this->prefix.'company_recurring_runs WHERE request_key=?',[$key])[0]??null;if(!$run||(int)$run['issuer_id']!==$issuer||(int)$run['schedule_id']!==$id||$run['run_date']!==$r['next_date']||$run['state']!=='processing')throw new RuntimeException('issuer_sales_write_unconfirmed');IssuerStorage::query($this->db,"UPDATE ".$this->prefix."company_recurring SET state='processing',last_error='' WHERE issuer_id=? AND id=?",[$issuer,$id]);if($this->owned($issuer,$actor,$id,true)['state']!=='processing')throw new RuntimeException('issuer_sales_write_unconfirmed');$this->audit($issuer,$actor,$id,'company_recurring_claimed');return [$r,$payload,$key];});
